def validate_metadata(self, handler):
        """ validate that kind=category does not change the categories """
        if handler.content_type != 'metadata':
            return

        # check that the metadata is a category
        if not handler.metadata.get('kind', '') == 'category':
            return

        # check that the category has not changed
        if handler.metadata.get('categories', None) is not None:
            raise InvalidMetadata('categories cannot be changed')

